insert into public.questions (id, kind, prompt, options, marks) values ('ae66390f-1587-5d1c-bf90-cc95654d627e', 'short', 'Explain how concentration gradients of oxygen are maintained at the alveoli.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ae66390f-1587-5d1c-bf90-cc95654d627e', 'Ventilation brings in fresh air, keeping O₂ concentration high in the alveoli [1]; continuous blood flow carries oxygenated blood away, keeping O₂ low in the blood [1]; a dense network of capillaries surrounds each alveolus, so the gradient is maintained over a large area [1].', 'Ventilation brings in fresh air, keeping O₂ concentration high in the alveoli [1]; continuous blood flow carries oxygenated blood away, keeping O₂ low in the blood [1]; a dense network of capillaries surrounds each alveolus, so the gradient is maintained over a large area [1].', '[{"text": "Marking point 1", "any": ["ventilation", "breathing", "fresh air", "air is replaced"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["blood flow", "blood carries", "continuous", "carried away"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["capillar", "blood vessels"], "all": [], "marks": 1}]'::jsonb, 'Ventilation brings in fresh air, keeping O₂ concentration high in the alveoli [1]; continuous blood flow carries oxygenated blood away, keeping O₂ low in the blood [1]; a dense network of capillaries surrounds each alveolus, so the gradient is maintained over a large area [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
