insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1fe5461b-55d8-5109-ac93-e6d704a858e1', 'Mineral ions are actively transported (using ATP) [1] into the xylem in the root [1]; water follows by osmosis, creating a positive pressure that pushes water up [1].', 'Mineral ions are actively transported (using ATP) [1] into the xylem in the root [1]; water follows by osmosis, creating a positive pressure that pushes water up [1].', '[{"text": "Marking point 1", "any": ["active transport", "pump", "atp"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ions", "mineral"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["osmosis", "water follows", "water moves in"], "all": [], "marks": 1}]'::jsonb, 'Mineral ions are actively transported (using ATP) [1] into the xylem in the root [1]; water follows by osmosis, creating a positive pressure that pushes water up [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
