insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1a268faf-dbac-5873-b794-adec5e450579', 'Blood flow to part of the heart is reduced or stopped [1]; so the cardiac muscle beyond the blockage gets too little O₂ and cannot respire aerobically [1]; this causes chest pain (angina) or the death of heart muscle cells (heart attack) [1].', 'Blood flow to part of the heart is reduced or stopped [1]; so the cardiac muscle beyond the blockage gets too little O₂ and cannot respire aerobically [1]; this causes chest pain (angina) or the death of heart muscle cells (heart attack) [1].', '[{"text": "Marking point 1", "any": ["oxygen", "o2", "blood supply"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["heart muscle", "cardiac muscle", "heart cells"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["die", "death", "heart attack", "infarction", "angina"], "all": [], "marks": 1}]'::jsonb, 'Blood flow to part of the heart is reduced or stopped [1]; so the cardiac muscle beyond the blockage gets too little O₂ and cannot respire aerobically [1]; this causes chest pain (angina) or the death of heart muscle cells (heart attack) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
