insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9a1ff73c-a107-5aae-9d2a-786b63ba2f5c', 'Adrenaline (first messenger) binds to the receptor outside and does not enter the cell [1]; via a G protein, adenylyl cyclase converts ATP to cAMP inside the cell [1]; cAMP carries the signal inside, activating protein kinases and amplifying the response (glycogen breakdown) [1].', 'Adrenaline (first messenger) binds to the receptor outside and does not enter the cell [1]; via a G protein, adenylyl cyclase converts ATP to cAMP inside the cell [1]; cAMP carries the signal inside, activating protein kinases and amplifying the response (glycogen breakdown) [1].', '[{"text": "Marking point 1", "any": ["does not enter", "first messenger", "receptor"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["adenylyl cyclase", "atp", "produced"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["kinase", "amplif", "inside", "glycogen"], "all": [], "marks": 1}]'::jsonb, 'Adrenaline (first messenger) binds to the receptor outside and does not enter the cell [1]; via a G protein, adenylyl cyclase converts ATP to cAMP inside the cell [1]; cAMP carries the signal inside, activating protein kinases and amplifying the response (glycogen breakdown) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
