insert into public.questions (id, kind, prompt, options, marks) values ('322f633e-a923-5821-bf85-0a208e7c5c03', 'short', 'Explain why signals can only pass in one direction across a synapse.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('322f633e-a923-5821-bf85-0a208e7c5c03', 'Neurotransmitter is stored in vesicles only in the presynaptic neuron [1]; receptors are only on the postsynaptic membrane, so the signal can only pass from pre to post [1].', 'Neurotransmitter is stored in vesicles only in the presynaptic neuron [1]; receptors are only on the postsynaptic membrane, so the signal can only pass from pre to post [1].', '[{"text": "Marking point 1", "any": ["only the presynaptic", "released from the presynaptic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["receptors only", "only the postsynaptic"], "all": [], "marks": 1}]'::jsonb, 'Neurotransmitter is stored in vesicles only in the presynaptic neuron [1]; receptors are only on the postsynaptic membrane, so the signal can only pass from pre to post [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d4392c5d-9170-5649-94af-a8159646d5dc', '322f633e-a923-5821-bf85-0a208e7c5c03', 11);
insert into public.questions (id, kind, prompt, options, marks) values ('0c9eeaaf-494d-57ef-8cc6-2171001afb88', 'short', 'Describe how an excitatory postsynaptic potential is generated at a cholinergic synapse.', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0c9eeaaf-494d-57ef-8cc6-2171001afb88', 'Depolarisation causes Ca²⁺ to enter the presynaptic neuron [1]; vesicles release acetylcholine by exocytosis [1]; acetylcholine diffuses across the synaptic cleft [1]; it binds to receptors, opening channels so Na⁺ enters and the postsynaptic membrane depolarises [1].', 'Depolarisation causes Ca²⁺ to enter the presynaptic neuron [1]; vesicles release acetylcholine by exocytosis [1]; acetylcholine diffuses across the synaptic cleft [1]; it binds to receptors, opening channels so Na⁺ enters and the postsynaptic membrane depolarises [1].', '[{"text": "Marking point 1", "any": ["calcium", "ca"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["exocytosis", "vesicles fuse", "released"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["diffuse", "cleft"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["receptor", "binds"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["sodium", "na", "depolari"], "all": [], "marks": 1}]'::jsonb, 'Depolarisation causes Ca²⁺ to enter the presynaptic neuron [1]; vesicles release acetylcholine by exocytosis [1]; acetylcholine diffuses across the synaptic cleft [1]; it binds to receptors, opening channels so Na⁺ enters and the postsynaptic membrane depolarises [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d4392c5d-9170-5649-94af-a8159646d5dc', '0c9eeaaf-494d-57ef-8cc6-2171001afb88', 12);
