insert into public.questions (id, kind, prompt, options, marks) values ('39974b60-0ee7-5322-bca3-3c4869c0c775', 'short', 'Explain how an action potential is propagated along a non-myelinated axon.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('39974b60-0ee7-5322-bca3-3c4869c0c775', 'Na⁺ ions entering at a depolarised region diffuse along the axon, creating local currents [1]; this raises the membrane potential of the adjacent region to threshold [1]; voltage-gated Na⁺ channels there open, so the action potential moves along [1].', 'Na⁺ ions entering at a depolarised region diffuse along the axon, creating local currents [1]; this raises the membrane potential of the adjacent region to threshold [1]; voltage-gated Na⁺ channels there open, so the action potential moves along [1].', '[{"text": "Marking point 1", "any": ["na diffuse", "local current"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["threshold", "next region", "adjacent"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["channels open", "voltage-gated", "sodium channels"], "all": [], "marks": 1}]'::jsonb, 'Na⁺ ions entering at a depolarised region diffuse along the axon, creating local currents [1]; this raises the membrane potential of the adjacent region to threshold [1]; voltage-gated Na⁺ channels there open, so the action potential moves along [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d4392c5d-9170-5649-94af-a8159646d5dc', '39974b60-0ee7-5322-bca3-3c4869c0c775', 18);
insert into public.questions (id, kind, prompt, options, marks) values ('bc426d96-e83d-5e42-b8a5-1a6f141d5522', 'short', 'Explain why impulses travel faster in myelinated axons.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bc426d96-e83d-5e42-b8a5-1a6f141d5522', 'Myelin insulates the axon so ions cannot cross there [1]; channels and pumps are clustered at the nodes of Ranvier [1]; the action potential jumps from node to node (saltatory conduction), covering the distance faster [1].', 'Myelin insulates the axon so ions cannot cross there [1]; channels and pumps are clustered at the nodes of Ranvier [1]; the action potential jumps from node to node (saltatory conduction), covering the distance faster [1].', '[{"text": "Marking point 1", "any": ["insulat", "myelin"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["node", "ranvier"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["jump", "saltatory", "node to node"], "all": [], "marks": 1}]'::jsonb, 'Myelin insulates the axon so ions cannot cross there [1]; channels and pumps are clustered at the nodes of Ranvier [1]; the action potential jumps from node to node (saltatory conduction), covering the distance faster [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d4392c5d-9170-5649-94af-a8159646d5dc', 'bc426d96-e83d-5e42-b8a5-1a6f141d5522', 19);
insert into public.questions (id, kind, prompt, options, marks) values ('0211c0ac-d49d-5d1c-9b92-be670f7c4e30', 'short', 'Explain the role of the threshold potential in generating an action potential.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0211c0ac-d49d-5d1c-9b92-be670f7c4e30', 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].', 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].', '[{"text": "Marking point 1", "any": ["voltage-gated sodium", "na channels open"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["all or nothing", "no action potential", "below threshold"], "all": [], "marks": 1}]'::jsonb, 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('d4392c5d-9170-5649-94af-a8159646d5dc', '0211c0ac-d49d-5d1c-9b92-be670f7c4e30', 20);
