insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('66b33e00-c321-5d9f-a389-551a00983462', 'The Na⁺/K⁺ pump moves 3 Na⁺ out for every 2 K⁺ in, so more positive charge leaves [1]; K⁺ leaks out through open channels (the membrane is more permeable to K⁺ than Na⁺) [1]; negatively charged proteins remain inside the cell [1].', 'The Na⁺/K⁺ pump moves 3 Na⁺ out for every 2 K⁺ in, so more positive charge leaves [1]; K⁺ leaks out through open channels (the membrane is more permeable to K⁺ than Na⁺) [1]; negatively charged proteins remain inside the cell [1].', '[{"text": "Marking point 1", "any": ["more positive", "more na"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["k diffuse out", "potassium out", "more permeable"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["proteins", "organic anions", "negatively charged"], "all": [], "marks": 1}]'::jsonb, 'The Na⁺/K⁺ pump moves 3 Na⁺ out for every 2 K⁺ in, so more positive charge leaves [1]; K⁺ leaks out through open channels (the membrane is more permeable to K⁺ than Na⁺) [1]; negatively charged proteins remain inside the cell [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
