insert into public.questions (id, kind, prompt, options, marks) values ('14ec6ef2-039b-5957-8ed3-6422db0b61ec', 'short', 'Explain how a sarcomere contracts.', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('14ec6ef2-039b-5957-8ed3-6422db0b61ec', 'Calcium ions are released and expose binding sites on actin [1]; myosin heads bind to actin, forming cross-bridges [1]; the heads swivel, pulling actin filaments towards the centre so filaments slide and the sarcomere shortens [1]; ATP is used to detach and re-cock the myosin heads so the cycle repeats [1].', 'Calcium ions are released and expose binding sites on actin [1]; myosin heads bind to actin, forming cross-bridges [1]; the heads swivel, pulling actin filaments towards the centre so filaments slide and the sarcomere shortens [1]; ATP is used to detach and re-cock the myosin heads so the cycle repeats [1].', '[{"text": "Marking point 1", "any": ["calcium", "ca"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cross-bridge", "myosin heads attach", "bind to actin"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pull", "power stroke", "swivel", "slide"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["atp"], "all": [], "marks": 1}]'::jsonb, 'Calcium ions are released and expose binding sites on actin [1]; myosin heads bind to actin, forming cross-bridges [1]; the heads swivel, pulling actin filaments towards the centre so filaments slide and the sarcomere shortens [1]; ATP is used to detach and re-cock the myosin heads so the cycle repeats [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0acaa99d-98d5-522f-bcff-c37bf33af029', '14ec6ef2-039b-5957-8ed3-6422db0b61ec', 8);
insert into public.questions (id, kind, prompt, options, marks) values ('c43a6a18-8c98-5272-ba7f-4e189e591e77', 'short', 'Explain why skeletal muscles occur in antagonistic pairs.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c43a6a18-8c98-5272-ba7f-4e189e591e77', 'A muscle can only exert force by contracting (pulling) [1]; so a second, antagonistic muscle is needed to pull in the opposite direction and stretch the first back to its original length [1].', 'A muscle can only exert force by contracting (pulling) [1]; so a second, antagonistic muscle is needed to pull in the opposite direction and stretch the first back to its original length [1].', '[{"text": "Marking point 1", "any": ["only contract", "only pull", "cannot push", "only exert force"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["stretch", "opposite", "relax", "lengthen"], "all": [], "marks": 1}]'::jsonb, 'A muscle can only exert force by contracting (pulling) [1]; so a second, antagonistic muscle is needed to pull in the opposite direction and stretch the first back to its original length [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
