insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ead56570-3bfe-596c-88e7-dbd65ecc0bbd', 'One motor neuron [1]; the group of muscle fibres it controls [1]; connected by neuromuscular junctions (synapses using acetylcholine) [1].', 'One motor neuron [1]; the group of muscle fibres it controls [1]; connected by neuromuscular junctions (synapses using acetylcholine) [1].', '[{"text": "Marking point 1", "any": ["motor neuron", "motor neurone"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["muscle fibres", "fibers"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["neuromuscular junction", "synapse"], "all": [], "marks": 1}]'::jsonb, 'One motor neuron [1]; the group of muscle fibres it controls [1]; connected by neuromuscular junctions (synapses using acetylcholine) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
