insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('71e899bc-425a-5d97-8af2-441bed94d668', 'Their fibres are orientated differently, so they move the ribcage in opposite directions [1]; when one layer contracts it stretches the other, storing energy in titin [1].', 'Their fibres are orientated differently, so they move the ribcage in opposite directions [1]; when one layer contracts it stretches the other, storing energy in titin [1].', '[{"text": "Marking point 1", "any": ["opposite", "different directions"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["stretch", "titin"], "all": [], "marks": 1}]'::jsonb, 'Their fibres are orientated differently, so they move the ribcage in opposite directions [1]; when one layer contracts it stretches the other, storing energy in titin [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
